def get_nest(ds):
    return ds.crs.healpix_order == "nest"

def get_nside(ds):
    return ds.crs.healpix_nside

# The dataset used in this section uses the old easygems CRS convention. 
# The new easygems (>=0.1.4) `guess_crs()` seems to be looking for these via 
# `cf_xarray`'s grid mapping mechanism, which fails on the old data format
# So we will need to assign "crs" coords of the dataset properly
def fix_crs(ds):
    import xarray as xr

    crs_scalar = xr.DataArray(
        attrs={
            "grid_mapping_name": "healpix",
            "healpix_nside": get_nside(ds),
            "healpix_order": str(ds.crs.healpix_order),
        }
    )
    return ds.assign_coords(crs=crs_scalar)
